// src/lib/mcp/tools/list-events.ts
var list_events_default = defineTool({
  name: "list_events",
  title: "List events",
  description: "List Ronda Priv\xE9 showcase events (festivals, concerts, nightclubs, conferences). Optionally filter by status or category.",
  inputSchema: {
    status: z.enum(["active", "upcoming"]).optional().describe("Filter by event status."),
    category: z.enum(["festival", "concert", "nightclub", "conference", "bar"]).optional().describe("Filter by event category.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ status, category }) => {
    const rows = events.filter((e) => status ? e.status === status : true).filter((e) => category ? e.category === category : true).map((e) => ({
      id: e.id,
      name: e.name,
      venue: e.venue,
      city: e.city,
      status: e.status,
      category: e.category,
      features: e.features,
      rating: e.rating,
      attendees: e.attendees
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(rows, null, 2) }],
      structuredContent: { events: rows }
    };
  }
});

// src/lib/mcp/tools/get-event.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.21.0";
import { z as z2 } from "npm:zod@^4.4.3";
var get_event_default = defineTool2({
  name: "get_event",
  title: "Get event details",
  description: "Get full details for one Ronda Priv\xE9 event by id, including vendors and menus.",
  inputSchema: {
    id: z2.string().min(1).describe("The event id (e.g. 'estereo-picnic-2026').")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const event = events.find((e) => e.id === id);
    if (!event) {
      return {
        content: [{ type: "text", text: `No event found with id '${id}'.` }],
        isError: true
      };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(event, null, 2) }],
      structuredContent: { event }
    };
  }
});

