// src/lib/mcp/tools/list-faq.ts
var faqDict = es_default.faq ?? {};
var asString = (v) => typeof v === "string" ? v : "";
var list_faq_default = defineTool3({
  name: "list_faq",
  title: "List FAQ",
  description: "List Ronda Priv\xE9 frequently asked questions with answers (Spanish). Optionally filter by category.",
  inputSchema: {
    category: z3.enum(["general", "attendees", "organizers", "technical"]).optional().describe("Filter by FAQ category.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ category }) => {
    const rows = faqItems.filter((f) => category ? f.category === category : true).map((f) => ({
      id: f.id,
      category: f.category,
      question: asString(faqDict[f.questionKey.replace(/^faq\./, "")]),
      answer: asString(faqDict[f.answerKey.replace(/^faq\./, "")])
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(rows, null, 2) }],
      structuredContent: { faq: rows }
    };
  }
});

