// src/lib/mcp/tools/list-glossary.ts
var terms = es_default.glossary?.terms ?? {};
var list_glossary_default = defineTool4({
  name: "list_glossary",
  title: "List glossary",
  description: "List Ronda Priv\xE9 industry glossary terms with definitions (Spanish). Optionally filter by category or search text.",
  inputSchema: {
    category: z4.enum(["sales", "venue", "tech", "spaces", "metrics"]).optional().describe("Filter by glossary category."),
    search: z4.string().optional().describe("Case-insensitive substring match on term or definition.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ category, search }) => {
    const q = search?.toLowerCase();
    const rows = GLOSSARY_TERMS.filter((g) => category ? g.category === category : true).map((g) => ({
      id: g.id,
      category: g.category,
      term: terms[g.id]?.term ?? g.id,
      definition: terms[g.id]?.definition ?? ""
    })).filter((r) => q ? r.term.toLowerCase().includes(q) || r.definition.toLowerCase().includes(q) : true);
    return {
      content: [{ type: "text", text: JSON.stringify(rows, null, 2) }],
      structuredContent: { glossary: rows }
    };
  }
});

